1	//! Interactive terminal UI.
2	//!
3	//! [`TerminalUI`] is the generic interactive UI used by every command
4	//! (init, status, list, run, …). For run-path workflow chrome and step
5	//! rendering, see [`crate::runner::display`].
6	
7	use console::Term;
8	use std::io::Write;
9	use std::sync::Arc;
10	
11	use crate::error::Result;
12	use crate::ui::surface::TerminalSurface;
13	
14	use super::{
15	    prompt_user, should_use_colors, BivvyTheme, NonInteractiveUI, OutputMode, OutputWriter,
16	    ProgressDisplay, ProgressSpinner, Prompt, PromptResult, Prompter, SpinnerFactory,
17	    SpinnerHandle, UiState, UserInterface,
18	};
19	
20	#[cfg(unix)]
21	use crate::shell::command::claim_foreground;
22	
23	/// Interactive terminal UI implementation.
24	///
25	/// During a workflow run an [`Arc<TerminalSurface>`] is attached via
26	/// [`TerminalUI::with_surface`]; output then flows through the surface
27	/// so it stays coordinated with the workflow's pinned bar and the
28	/// active step's transient region. Outside of a run the surface is
29	/// `None` and output is written directly to the terminal.
30	pub struct TerminalUI {
31	    term: Term,
32	    theme: BivvyTheme,
33	    mode: OutputMode,
34	    surface: Option<Arc<TerminalSurface>>,
35	}
36	
37	impl TerminalUI {
38	    /// Create a new terminal UI.
39	    pub fn new(mode: OutputMode) -> Self {
40	        let theme = if should_use_colors() {
41	            BivvyTheme::new()
42	        } else {
43	            BivvyTheme::plain()
44	        };
45	
46	        Self {
47	            term: Term::stdout(),
48	            theme,
49	            mode,
50	            surface: None,
51	        }
52	    }
53	
54	    /// Print a line through the surface (above bars) or directly to
55	    /// the terminal if no surface is attached.
56	    fn println(&mut self, line: &str) {
57	        if let Some(surface) = &self.surface {
58	            surface.println(line);
59	        } else {
60	            writeln!(self.term, "{}", line).ok();
61	        }
62	    }
63	}
64	
65	impl OutputWriter for TerminalUI {
66	    fn message(&mut self, msg: &str) {
67	        if self.mode.shows_status() {
68	            self.println(msg);
69	        }
70	    }
71	
72	    fn success(&mut self, msg: &str) {
73	        if self.mode.shows_status() {
74	            self.println(&self.theme.format_success(msg).to_string());
75	        }
76	    }
77	
78	    fn warning(&mut self, msg: &str) {
79	        if self.mode.shows_status() {
80	            self.println(&self.theme.format_warning(msg).to_string());
81	        }
82	    }
83	
84	    fn error(&mut self, msg: &str) {
85	        self.println(&self.theme.format_error(msg).to_string());
86	    }
87	
88	    fn show_hint(&mut self, hint: &str) {
89	        if self.mode.shows_status() {
90	            self.println(&self.theme.hint.apply_to(hint).to_string());
91	            self.println("");
92	        }
93	    }
94	
95	    fn show_error_block(&mut self, command: &str, output: &str, hint: Option<&str>, indent: usize) {
96	        let b = &self.theme.border;
97	        let pad = " ".repeat(indent);
98	        let mut lines = vec![
99	            format!(
100	                "{}{} {}",
101	                pad,
102	                b.apply_to("┌─"),
103	                b.apply_to("Command ──────────────────────────")
104	            ),
105	            format!(
106	                "{}{} {}",
107	                pad,
108	                b.apply_to("│"),
109	                self.theme.command.apply_to(command)
110	            ),
111	        ];
112	
113	        if !output.is_empty() {
114	            lines.push(format!(
115	                "{}{} {}",
116	                pad,
117	                b.apply_to("├─"),
118	                b.apply_to("Output ───────────────────────────")
119	            ));
120	            for line in output.lines() {
121	                lines.push(format!("{}{} {}", pad, b.apply_to("│"), line));
122	            }
123	        }
124	
125	        lines.push(format!(
126	            "{}{}",
127	            pad,
128	            b.apply_to("└────────────────────────────────────")
129	        ));
130	
131	        if let Some(h) = hint {
132	            lines.push(String::new());
133	            lines.push(format!(
134	                "{}{} {}",
135	                pad,
136	                self.theme.hint.apply_to("Hint:"),
137	                self.theme.hint.apply_to(h)
138	            ));
139	        }
140	
141	        for line in &lines {
142	            self.println(line);
143	        }
144	    }
145	}
146	
147	impl Prompter for TerminalUI {
148	    fn prompt(&mut self, prompt: &Prompt) -> Result<PromptResult> {
149	        // Re-claim foreground process group: child commands may have
150	        // stolen it on exit, leaving us unable to read input.
151	        #[cfg(unix)]
152	        claim_foreground();
153	
154	        if let Some(surface) = &self.surface {
155	            surface.with_cursor_freed(|| prompt_user(prompt, &self.term))
156	        } else {
157	            prompt_user(prompt, &self.term)
158	        }
159	    }
160	}
161	
162	impl SpinnerFactory for TerminalUI {
163	    fn start_spinner(&mut self, message: &str) -> Box<dyn SpinnerHandle> {
164	        if self.mode.shows_spinners() {
165	            // Outside a run path: ad-hoc spinner with no surface
166	            // coordination. Used by init/status/etc. for one-off
167	            // operations.
168	            Box::new(ProgressSpinner::new(message))
169	        } else {
170	            Box::new(ProgressSpinner::hidden())
171	        }
172	    }
173	
174	    fn start_spinner_indented(&mut self, message: &str, indent: usize) -> Box<dyn SpinnerHandle> {
175	        if self.mode.shows_spinners() {
176	            Box::new(ProgressSpinner::with_indent(message, indent))
177	        } else {
178	            Box::new(ProgressSpinner::hidden())
179	        }
180	    }
181	}
182	
183	impl ProgressDisplay for TerminalUI {
184	    fn show_header(&mut self, title: &str) {
185	        if self.mode.shows_status() {
186	            self.println(&format!("\n{}\n", self.theme.format_header(title)));
187	        }
188	    }
189	
190	    fn show_progress(&mut self, current: usize, total: usize) {
191	        if self.mode.shows_status() {
192	            self.println(
193	                &self
194	                    .theme
195	                    .dim
196	                    .apply_to(format!("[{}/{}]", current, total))
197	                    .to_string(),
198	            );
199	        }
200	    }
201	}
202	
203	impl UiState for TerminalUI {
204	    fn output_mode(&self) -> OutputMode {
205	        self.mode
206	    }
207	
208	    fn is_interactive(&self) -> bool {
209	        self.term.is_term()
210	    }
211	
212	    fn set_output_mode(&mut self, mode: OutputMode) {
213	        self.mode = mode;
214	    }
215	
216	    fn attach_surface(&mut self, surface: Arc<TerminalSurface>) {
217	        self.surface = Some(surface);
218	    }
219	
