1	//! Non-interactive UI for CI/headless environments.
2	
3	use crate::error::{BivvyError, Result};
4	
5	use super::theme::BivvyTheme;
6	use super::{
7	    OutputMode, OutputWriter, ProgressDisplay, Prompt, PromptResult, PromptType, Prompter,
8	    SpinnerFactory, SpinnerHandle, UiState,
9	};
10	
11	/// UI implementation for non-interactive mode.
12	///
13	/// Used by every command (init, status, list, run, …) when running
14	/// without a TTY. Run-path workflow chrome lives in
15	/// [`crate::runner::display::NonInteractiveWorkflowDisplay`] — this
16	/// type only handles generic [`UserInterface`] traits.
17	pub struct NonInteractiveUI {
18	    mode: OutputMode,
19	    #[allow(dead_code)]
20	    is_ci: bool,
21	}
22	
23	impl NonInteractiveUI {
24	    /// Create a new non-interactive UI.
25	    pub fn new(mode: OutputMode) -> Self {
26	        Self {
27	            mode,
28	            is_ci: crate::shell::is_ci(),
29	        }
30	    }
31	
32	    /// Create with explicit CI flag (for testing).
33	    pub fn with_ci(mode: OutputMode, is_ci: bool) -> Self {
34	        Self { mode, is_ci }
35	    }
36	}
37	
38	impl OutputWriter for NonInteractiveUI {
39	    fn message(&mut self, msg: &str) {
40	        if self.mode.shows_status() {
41	            println!("{}", msg);
42	        }
43	    }
44	
45	    fn success(&mut self, msg: &str) {
46	        if self.mode.shows_status() {
47	            println!("✓ {}", msg);
48	        }
49	    }
50	
51	    fn warning(&mut self, msg: &str) {
52	        if self.mode.shows_status() {
53	            eprintln!("⚠ {}", msg);
54	        }
55	    }
56	
57	    fn error(&mut self, msg: &str) {
58	        eprintln!("✗ {}", msg);
59	    }
60	
61	    fn show_hint(&mut self, hint: &str) {
62	        if self.mode.shows_status() {
63	            println!("  💡 {}", hint);
64	        }
65	    }
66	
67	    fn show_error_block(&mut self, command: &str, output: &str, hint: Option<&str>, indent: usize) {
68	        let pad = " ".repeat(indent);
69	        eprintln!();
70	        eprintln!("{}┌─ Command ──────────────────────────", pad);
71	        eprintln!("{}│ {}", pad, command);
72	        if !output.is_empty() {
73	            eprintln!("{}├─ Output ───────────────────────────", pad);
74	            for line in output.lines() {
75	                eprintln!("{}│ {}", pad, line);
76	            }
77	        }
78	        eprintln!("{}└────────────────────────────────────", pad);
79	        if let Some(h) = hint {
80	            eprintln!();
81	            eprintln!("{}Hint: {}", pad, h);
82	        }
83	    }
84	}
85	
86	impl Prompter for NonInteractiveUI {
87	    fn prompt(&mut self, prompt: &Prompt) -> Result<PromptResult> {
88	        let is_multiselect = matches!(prompt.prompt_type, PromptType::MultiSelect { .. });
89	
90	        // Check environment override (KEY=value, e.g. BUMP=minor).
91	        // This is handled by prompt_user for TerminalUI, but
92	        // NonInteractiveUI doesn't call prompt_user, so check here too.
93	        if let Some(result) = super::prompts::env_override(prompt) {
94	            return Ok(result);
95	        }
96	
97	        // Use default
98	        if let Some(default) = &prompt.default {
99	            if is_multiselect {
100	                let values: Vec<String> =
101	                    default.split(',').map(|s| s.trim().to_string()).collect();
102	                return Ok(PromptResult::Strings(values));
103	            }
104	            return Ok(PromptResult::String(default.clone()));
105	        }
106	
107	        Err(BivvyError::ConfigValidationError {
108	            message: format!(
109	                "Cannot prompt for '{}' in non-interactive mode (no default value)",
110	                prompt.key
111	            ),
112	        })
113	    }
114	}
115	
116	impl SpinnerFactory for NonInteractiveUI {
117	    fn start_spinner(&mut self, message: &str) -> Box<dyn SpinnerHandle> {
118	        if self.mode.shows_spinners() {
119	            println!("  {}", message);
120	        }
121	        Box::new(NoopSpinner { indent: 0 })
122	    }
123	
124	    fn start_spinner_indented(&mut self, message: &str, indent: usize) -> Box<dyn SpinnerHandle> {
125	        if self.mode.shows_spinners() {
126	            let prefix = " ".repeat(indent);
127	            println!("{}{}", prefix, message);
128	        }
129	        Box::new(NoopSpinner { indent })
130	    }
131	}
132	
133	impl ProgressDisplay for NonInteractiveUI {
134	    fn show_header(&mut self, title: &str) {
135	        if self.mode.shows_status() {
136	            println!("\n{}\n", title);
137	        }
138	    }
139	
140	    fn show_progress(&mut self, current: usize, total: usize) {
141	        if self.mode.shows_status() {
142	            println!("[{}/{}]", current, total);
143	        }
144	    }
145	}
146	
147	impl UiState for NonInteractiveUI {
148	    fn output_mode(&self) -> OutputMode {
149	        self.mode
150	    }
151	
152	    fn is_interactive(&self) -> bool {
153	        false
154	    }
155	
156	    fn set_output_mode(&mut self, mode: OutputMode) {
157	        self.mode = mode;
158	    }
159	}
160	
161	/// Spinner that does nothing (for non-interactive mode).
162	struct NoopSpinner {
163	    indent: usize,
164	}
165	
166	impl SpinnerHandle for NoopSpinner {
167	    fn set_message(&mut self, _msg: &str) {}
168	
169	    fn finish_success(&mut self, msg: &str) {
170	        let prefix = " ".repeat(self.indent);
171	        let theme = BivvyTheme::new();
172	        println!("{}{}", prefix, theme.format_success(msg));
173	    }
174	
175	    fn finish_error(&mut self, msg: &str) {
176	        let prefix = " ".repeat(self.indent);
177	        let theme = BivvyTheme::new();
178	        println!("{}{}", prefix, theme.format_error(msg));
179	    }
180	
181	    fn finish_skipped(&mut self, msg: &str) {
182	        let prefix = " ".repeat(self.indent);
183	        let theme = BivvyTheme::new();
184	        println!("{}{}", prefix, theme.format_skipped(msg));
185	    }
186	
187	    fn finish_and_clear(&mut self) {
188	        // No-op for non-interactive: nothing to clear
189	    }
190	}
191	
192	#[cfg(test)]
193	mod tests {
194	    use super::*;
195	
196	    #[test]
197	    fn non_interactive_is_not_interactive() {
198	        let ui = NonInteractiveUI::new(OutputMode::Normal);
199	        assert!(!ui.is_interactive());
200	    }
201	
202	    #[test]
203	    fn prompt_uses_default() {
204	        let mut ui = NonInteractiveUI::new(OutputMode::Normal);
205	        let prompt = Prompt {
206	            key: "test".to_string(),
207	            question: "Test?".to_string(),
208	            prompt_type: PromptType::Input,
209	            default: Some("default_value".to_string()),
210	        };
211	
212	        let result = ui.prompt(&prompt).unwrap();
213	        assert_eq!(result.as_string(), "default_value");
214	    }
215	
216	    #[test]
217	    fn prompt_fails_without_default() {
218	        let mut ui = NonInteractiveUI::new(OutputMode::Normal);
219	        let prompt = Prompt {
220	            key: "test".to_string(),
221	            question: "Test?".to_string(),
222	            prompt_type: PromptType::Input,
223	            default: None,
224	        };
225	
226	        let result = ui.prompt(&prompt);
227	        assert!(result.is_err());
228	    }
229	
230	    #[test]
231	    fn prompt_uses_env_override() {
232	        // Set env var matching the prompt key (uppercase)
233	        std::env::set_var("TEST_PROMPT_OVERRIDE", "override");
234	
235	        let mut ui = NonInteractiveUI::new(OutputMode::Normal);
236	        let prompt = Prompt {
237	            key: "test_prompt_override".to_string(),
238	            question: "Test?".to_string(),
239	            prompt_type: PromptType::Input,
240	            default: Some("default".to_string()),
241	        };
242	
243	        let result = ui.prompt(&prompt).unwrap();
244	        assert_eq!(result.as_string(), "override");
245	
246	        std::env::remove_var("TEST_PROMPT_OVERRIDE");
247	    }
248	
249	    #[test]
250	    fn output_mode_preserved() {
251	        let ui = NonInteractiveUI::new(OutputMode::Quiet);
252	        assert_eq!(ui.output_mode(), OutputMode::Quiet);
253	    }
254	
255	    #[test]
256	    fn noop_spinner_methods() {
257	        let mut spinner = NoopSpinner { indent: 0 };
258	        spinner.set_message("test");
259	        spinner.finish_success("done");
260	    }
261	
262	    #[test]
263	    fn noop_spinner_error() {
264	        let mut spinner = NoopSpinner { indent: 0 };
265	        spinner.finish_error("failed");
266	    }
267	
268	    #[test]
269	    fn noop_spinner_skipped() {
270	        let mut spinner = NoopSpinner { indent: 0 };
271	        spinner.finish_skipped("skipped");
272	    }
273	
274	    #[test]
275	    fn multiselect_prompt_uses_default() {
276	        let mut ui = NonInteractiveUI::new(OutputMode::Normal);
277	        let prompt = Prompt {
278	            key: "steps".to_string(),
279	            question: "Select steps".to_string(),
280	            prompt_type: PromptType::MultiSelect { options: vec![] },
281	            default: Some("bundler,cargo".to_string()),
282	        };
283	
284	        let result = ui.prompt(&prompt).unwrap();
285	        assert!(matches!(result, PromptResult::Strings(_)));
286	        assert_eq!(result.as_string(), "bundler,cargo");
287	    }
288	
289	    #[test]
290	    fn multiselect_prompt_uses_env_override() {
291	        std::env::set_var("MULTISELECT_OVERRIDE_STEPS", "npm");
292	
293	        let mut ui = NonInteractiveUI::new(OutputMode::Normal);
294	        let prompt = Prompt {
295	            key: "multiselect_override_steps".to_string(),
296	            question: "Select steps".to_string(),
297	            prompt_type: PromptType::MultiSelect { options: vec![] },
298	            default: Some("bundler,cargo".to_string()),
299	        };
300	
301	        let result = ui.prompt(&prompt).unwrap();
302	        assert!(matches!(result, PromptResult::Strings(_)));
303	        assert_eq!(result.as_string(), "npm");
304	
305	        std::env::remove_var("MULTISELECT_OVERRIDE_STEPS");
306	    }
