    checker: &mut GapChecker<'_>,
    ui: &mut dyn UserInterface,
    interactive: bool,
    ctx: &InstallerContext<'_>,
) -> Result<bool> {
    if gaps.is_empty() {
        return Ok(true);
    }

    let mut blocking = Vec::new();

    for gap in gaps {
        let outcome = if interactive {
            handle_gap_interactive(gap, checker, ui, ctx)
        } else {
            handle_gap_non_interactive(gap, ui)
        };

        match outcome {
            Outcome::Resolved | Outcome::CanProceed => {}
            Outcome::Skip { reason } => {
                ui.warning(&reason);
                return Ok(false);
            }
            Outcome::Blocked { requirement } => {
                blocking.push(requirement);
            }
        }
    }

    if blocking.is_empty() {
        Ok(true)
    } else {
        let names: Vec<&str> = blocking.iter().map(|s| s.as_str()).collect();
        Err(BivvyError::RequirementMissing {
            requirement: names.join(", "),
            message: format!(
                "Missing requirements: {}. Run 'bivvy lint' for details.",
                names.join(", ")
            ),
        })
    }
}

/// Accumulated PATH additions, shared between `prepend_path` and `run_command`
/// in the default installer context. Avoids mutating the global process
/// environment with `set_var`.
type PathAdditions = Arc<Mutex<Vec<std::path::PathBuf>>>;

/// Build the default `InstallerContext` for production use.
///
/// PATH modifications are accumulated in a shared list rather than mutating
/// the global process environment. The `run_command` closure prepends these
/// additions to the inherited PATH when spawning child processes.
pub fn default_context() -> InstallerContext<'static> {
    // Leaked so the closures can have 'static lifetime (matches previous API).
    // Only one InstallerContext is created per workflow run, so the leak is bounded.
    let additions: &'static PathAdditions = Box::leak(Box::new(Arc::new(Mutex::new(Vec::new()))));

    let run_additions = additions.clone();
    let prepend_additions = additions.clone();

    InstallerContext {
        run_command: Box::leak(Box::new(move |cmd: &str| {
            let mut command = std::process::Command::new("sh");
            command.arg("-c").arg(cmd);

            // Build PATH with accumulated additions prepended
            let extras = run_additions.lock().unwrap();
            if !extras.is_empty() {
                let current = std::env::var("PATH").unwrap_or_default();
                let prefix = extras
                    .iter()
                    .map(|p| p.to_string_lossy().to_string())
                    .collect::<Vec<_>>()
                    .join(":");
                let new_path = format!("{}:{}", prefix, current);
                command.env("PATH", new_path);
            }

            command.status().is_ok_and(|s| s.success())
        })),
        check_network: &|| {
            use std::net::TcpStream;
            use std::time::Duration;
            let timeout = Duration::from_secs(2);
            let addr: std::net::SocketAddr = "1.1.1.1:443".parse().unwrap();
            TcpStream::connect_timeout(&addr, timeout).is_ok()
        },
        prepend_path: Box::leak(Box::new(move |dir: &Path| {
            let mut extras = prepend_additions.lock().unwrap();
            let path = dir.to_path_buf();
            if !extras.contains(&path) {
                extras.push(path);
            }
        })),
    }
}

#[derive(Debug, PartialEq)]
enum Outcome {
    Resolved,
    CanProceed,
    Skip { reason: String },
    Blocked { requirement: String },
}

fn handle_gap_interactive(
    gap: &GapResult,
    checker: &mut GapChecker<'_>,
    ui: &mut dyn UserInterface,
    ctx: &InstallerContext<'_>,
) -> Outcome {
    match &gap.status {
        RequirementStatus::Satisfied => Outcome::Resolved,
        RequirementStatus::Inactive {
            binary_path,
            activation_hint,
            ..
        } => handle_inactive(&gap.requirement, binary_path, activation_hint, checker, ctx),
        RequirementStatus::ServiceDown {
            start_command,
            start_hint,
            ..
        } => handle_service_down(
            &gap.requirement,
            start_command.as_deref(),
            start_hint,
            checker,
            ui,
            ctx,
        ),
        RequirementStatus::Missing {
            install_template,
            install_hint,
        } => handle_missing(
            &gap.requirement,
            install_template.as_deref(),
            install_hint.as_deref(),
            checker,
            ui,
            ctx,
        ),
        RequirementStatus::SystemOnly {
            warning,
            install_template,
            ..
        } => handle_system_only(
            &gap.requirement,
            warning,
            install_template.as_deref(),
            checker,
            ui,
            ctx,
        ),
        RequirementStatus::Unknown => Outcome::Blocked {
            requirement: gap.requirement.clone(),
        },
    }
}

fn handle_gap_non_interactive(gap: &GapResult, ui: &mut dyn OutputWriter) -> Outcome {
    match &gap.status {
        RequirementStatus::Satisfied => Outcome::Resolved,
        RequirementStatus::SystemOnly { warning, .. } => {
            ui.warning(warning);
