289	/// Custom yes/no prompt with `›`/`·` indicators and `y`/`n` keyboard shortcuts.
290	///
291	/// Renders options below the prompt question, indented to align with
292	/// the step name. Supports arrow keys, j/k, Enter/Space, y/n, and Escape.
293	///
294	/// # SIGTTOU / SIGTTIN safety
295	///
296	/// This function calls `term.read_key()` directly, which:
297	///   - Uses `tcsetattr` to enter raw mode → triggers SIGTTOU
298	///   - Reads from the terminal fd → triggers SIGTTIN
299	///
300	/// When bivvy is not the terminal's foreground process group (e.g.,
301	/// launched via `cargo run`), zsh suspends the process with
302	/// "suspended (tty output)" or "suspended (tty input)".
303	///
304	/// **This function depends on signal ignores in `main.rs`.**
305	/// Without both `libc::signal(libc::SIGTTOU, libc::SIG_IGN)` and
306	/// `libc::signal(libc::SIGTTIN, libc::SIG_IGN)` in main(), calling
307	/// this function will crash the entire run command.
308	///
309	/// DO NOT remove the signal ignores in main.rs without also removing
310	/// the direct `term.read_key()` call here. See regression tests:
311	/// `yes_no_prompt_does_not_crash_on_non_tty` and
312	/// `yes_no_and_multi_option_selects_error_consistently`.
313	fn prompt_yes_no(prompt: &Prompt, options: &[PromptOption], term: &Term) -> Result<PromptResult> {
314	    let dumb = super::is_dumb_term();
315	
316	    let default_idx = prompt
317	        .default
318	        .as_ref()
319	        .and_then(|d| options.iter().position(|o| o.value == *d))
320	        .unwrap_or(0);
321	
322	    let mut sel = default_idx;
323	
324	    // Calculate indent from leading whitespace in the question text.
325	    // Questions are pre-indented to align with the step header above.
326	    // No leading whitespace and no bracket → no indent (e.g., "Run setup now?").
327	    let leading_ws = prompt.question.len() - prompt.question.trim_start().len();
328	    let pad = if leading_ws > 0 {
329	        " ".repeat(leading_ws)
330	    } else if let Some(bracket_pos) = prompt.question.find(']') {
331	        " ".repeat(bracket_pos + 2)
332	    } else {
333	        String::new()
334	    };
335	
336	    let active_prefix = Style::new().bold();
337	    let active_style = Style::new().bold();
338	    let inactive_prefix = Style::new().dim();
339	    let inactive_style = Style::new().dim();
340	
341	    // Enter raw mode BEFORE writing any prompt output. On macOS,
342	    // keystrokes that arrive while in canonical (cooked) mode are lost
343	    // when tcsetattr switches to raw mode — the canonical buffer is not
344	    // drained into the non-canonical read queue. By setting raw mode
345	    // first, any keystroke (from user or PTY test harness) lands
346	    // directly in the raw input queue and is immediately available.
347	    //
348	    // Guard is dropped after the selection, restoring cooked mode for
349	    // normal output.
350	    let _raw_guard = RawModeGuard::enter(term).map_err(BivvyError::Io)?;
351	
352	    // Write prompt question
353	    term.write_line(&prompt.question).map_err(BivvyError::Io)?;
354	
355	    // Hide cursor with RAII guard — cursor is restored on drop (panic, Ctrl+C, early return).
356	    // Dumb terminals don't support cursor visibility, so skip the CSI sequence.
357	    let _cursor_guard = if dumb {
358	        None
359	    } else {
360	        Some(CursorGuard::new(term).map_err(BivvyError::Io)?)
361	    };
362	
363	    // Draw initial option lines
364	    for (i, opt) in options.iter().enumerate() {
365	        let line = if i == sel {
366	            format!(
367	                "{}{} {}",
368	                pad,
369	                active_prefix.apply_to("›"),
370	                active_style.apply_to(&opt.label)
371	            )
372	        } else {
373	            format!(
374	                "{}{} {}",
375	                pad,
376	                inactive_prefix.apply_to("·"),
377	                inactive_style.apply_to(&opt.label)
378	            )
379	        };
380	        term.write_line(&line).map_err(BivvyError::Io)?;
381	    }
382	    term.flush().map_err(BivvyError::Io)?;
383	
384	    loop {
385	        // Read key — terminal is already in raw mode so read_key() is a
386	        // no-op mode switch (raw→raw). Characters are available immediately.
387	        let key = term.read_key().map_err(BivvyError::Io)?;
388	
389	        let chosen = match key {
390	            Key::Char('y') | Key::Char('Y') => options.iter().position(|o| o.value == "yes"),
391	            Key::Char('n') | Key::Char('N') => options.iter().position(|o| o.value == "no"),
392	            Key::Enter | Key::Char(' ') => Some(sel),
393	            Key::Escape => {
394	                // Treat Escape as "no" (matching dialoguer's abort behavior).
395	                // Find "no" option; fall back to default if somehow absent.
396	                let no_idx = options
397	                    .iter()
398	                    .position(|o| o.value == "no")
399	                    .unwrap_or(default_idx);
400	                Some(no_idx)
401	            }
402	            Key::ArrowDown | Key::Tab | Key::Char('j') => {
403	                sel = (sel + 1) % options.len();
404	                None
405	            }
406	            Key::ArrowUp | Key::BackTab | Key::Char('k') => {
407	                sel = (sel + options.len() - 1) % options.len();
408	                None
409	            }
410	            _ => None,
411	        };
412	
413	        if let Some(idx) = chosen {
414	            // Drop raw mode before writing answer text — restores output
415	            // processing (OPOST) so \n maps to \r\n correctly.
416	            drop(_raw_guard);
417	
418	            let (icon, answer_label) = if options[idx].value == "yes" {
419	                (Style::new().green().apply_to("✓"), "Yes")
420	            } else {
421	                (Style::new().dim().apply_to("·"), "No")
422	            };
423	
424	            if dumb {
425	                // Forward-only: print answer below the options, no clearing.
426	                term.write_line(&format!("{}{} {}", pad, icon, answer_label))
427	                    .map_err(BivvyError::Io)?;
428	            } else {
429	                // Clear option lines
430	                term.clear_last_lines(options.len())
431	                    .map_err(BivvyError::Io)?;
432	                // Clear the prompt question line
433	                term.clear_last_lines(1).map_err(BivvyError::Io)?;
434	                // Re-print prompt question, then answer on a new line with indicator
435	                term.write_line(&prompt.question).map_err(BivvyError::Io)?;
436	                term.write_line(&format!("{}{} {}", pad, icon, answer_label))
437	                    .map_err(BivvyError::Io)?;
438	            }
439	
440	            // _cursor_guard is dropped here, restoring the cursor.
441	            return Ok(PromptResult::String(options[idx].value.clone()));
442	        }
443	
444	        if !dumb {
445	            // Clear option lines for redraw (cursor movement not supported on dumb)
446	            term.clear_last_lines(options.len())
447	                .map_err(BivvyError::Io)?;
448	
449	            // Redraw option lines with updated selection
450	            for (i, opt) in options.iter().enumerate() {
451	                let line = if i == sel {
452	                    format!(
453	                        "{}{} {}",
454	                        pad,
455	                        active_prefix.apply_to("›"),
456	                        active_style.apply_to(&opt.label)
457	                    )
458	                } else {
459	                    format!(
460	                        "{}{} {}",
461	                        pad,
462	                        inactive_prefix.apply_to("·"),
463	                        inactive_style.apply_to(&opt.label)
464	                    )
465	                };
466	                term.write_line(&line).map_err(BivvyError::Io)?;
467	            }
468	            term.flush().map_err(BivvyError::Io)?;
469	        }
470	    }
471	}
