#[allow(clippy::too_many_arguments)]
fn handle_prompt(
    &self,
    prompt_key: &str,
    eval_result: &EvaluationResult,
    step_pad: &str,
    _needs_force: bool,
    event_bus: &mut EventBus,
    ui: &mut dyn UserInterface,
    step_display: &mut dyn StepDisplay,
) -> Result<Option<StepAction>> {
    if prompt_key.starts_with("rerun_") {
