    #[test]
    fn read_key_safe_converts_panic_to_error() {
        // Verify that a panic inside the key-reading closure is caught and
        // converted to an IO error rather than unwinding the thread.
        let result: std::result::Result<Key, BivvyError> =
            match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                panic!("simulated console panic")
            })) {
                Ok(Ok(key)) => Ok(key),
                Ok(Err(e)) => Err(BivvyError::Io(e)),
                Err(_) => Err(eof_error()),
            };

        assert!(result.is_err());
