//! Interactive prompts.

use console::{style, Key, Style, Term};
use dialoguer::theme::ColorfulTheme;
use dialoguer::{Confirm, Input, MultiSelect, Select};

use crate::error::{BivvyError, Result};

use super::{Prompt, PromptOption, PromptResult, PromptType};

/// ASCII EOT (End of Transmission) — the byte sent by Ctrl+D in raw mode.
const CTRL_D: char = '\x04';

/// Convert dialoguer errors to BivvyError.
fn map_dialoguer_err(e: dialoguer::Error) -> BivvyError {
    BivvyError::Io(e.into())
}

/// IO error returned when the user signals EOF (Ctrl+D).
fn eof_error() -> BivvyError {
    BivvyError::Io(std::io::Error::new(
        std::io::ErrorKind::UnexpectedEof,
        "input closed (Ctrl+D)",
    ))
}

/// Read a key from the terminal, catching panics from the console crate.
///
/// Console 0.16.x may panic internally on EOF/Ctrl+D depending on platform
/// and terminal state. This wrapper converts such panics to IO errors.
fn read_key_safe(term: &Term) -> std::result::Result<Key, BivvyError> {
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| term.read_key())) {
        Ok(Ok(key)) => Ok(key),
        Ok(Err(e)) => Err(BivvyError::Io(e)),
        Err(_) => Err(eof_error()),
    }
}

/// Run a dialoguer interaction, catching internal panics.
///
/// Dialoguer 0.12.x may panic on EOF/Ctrl+D due to unwrap calls in its
/// rendering or input handling. This wrapper converts such panics to errors.
fn catch_interact<T>(f: impl FnOnce() -> std::result::Result<T, dialoguer::Error>) -> Result<T> {
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(f)) {
        Ok(Ok(val)) => Ok(val),
        Ok(Err(e)) => Err(map_dialoguer_err(e)),
        Err(_) => Err(eof_error()),
    }
}

/// Dialoguer theme without the default yellow `?` prefix.
fn prompt_theme() -> ColorfulTheme {
    ColorfulTheme {
        prompt_prefix: style("".to_string()),
        ..ColorfulTheme::default()
    }
}

/// Check for an environment variable override for a prompt.
///
/// Users can skip any prompt by setting an env var matching the prompt key:
///   `BUMP=minor bivvy run --workflow release`
///
/// The lookup is case-insensitive on the key side: a prompt with key "bump"
/// matches env var `BUMP`, `bump`, or `Bump`.
pub(crate) fn env_override(prompt: &Prompt) -> Option<PromptResult> {
    let env_key = prompt.key.to_uppercase();
    let value = std::env::var(&env_key).ok()?;

    let is_multiselect = matches!(prompt.prompt_type, PromptType::MultiSelect { .. });
    if is_multiselect {
        let values: Vec<String> = value.split(',').map(|s| s.trim().to_string()).collect();
        Some(PromptResult::Strings(values))
    } else {
        Some(PromptResult::String(value))
    }
}

/// Prompt the user for input.
///
/// Before showing any interactive prompt, checks for an environment variable
/// matching the prompt key (e.g., `BUMP=minor` for a prompt with key "bump").
/// This works in both interactive and non-interactive modes.
pub fn prompt_user(prompt: &Prompt, term: &Term) -> Result<PromptResult> {
    if let Some(result) = env_override(prompt) {
        return Ok(result);
    }

    match &prompt.prompt_type {
        PromptType::Confirm => prompt_confirm(prompt, term),
        PromptType::Input => prompt_input(prompt, term),
        PromptType::Select { options } => prompt_select(prompt, options, term),
        PromptType::MultiSelect { options } => prompt_multiselect(prompt, options, term),
    }
}

