+                std::io::ErrorKind::BrokenPipe,
+                "pipe broken",
+            )))
+        });
+
+        assert!(result.is_err());
+        let err = result.unwrap_err();
+        assert!(
+            err.to_string().contains("pipe broken"),
+            "should preserve the original error: {}",
+            err
+        );
+    }
+
+    #[test]
+    fn eof_error_is_unexpected_eof_kind() {
+        let err = eof_error();
+        if let BivvyError::Io(io_err) = err {
+            assert_eq!(io_err.kind(), std::io::ErrorKind::UnexpectedEof);
+        } else {
+            panic!("expected BivvyError::Io variant");
+        }
+    }
+
+    #[test]
+    fn ctrl_d_constant_is_0x04() {
+        assert_eq!(CTRL_D, '\x04');
+    }
 }

